// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListBudgets The ceilings configured per scope
	// (GET /admin/budgets)
	ListBudgets(ctx context.Context, request ListBudgetsRequestObject) (ListBudgetsResponseObject, error)
	// DeleteBudget Remove a scope's ceiling
	// (DELETE /admin/budgets/{scope})
	DeleteBudget(ctx context.Context, request DeleteBudgetRequestObject) (DeleteBudgetResponseObject, error)
	// PutBudget Set a scope's ceiling
	// (PUT /admin/budgets/{scope})
	PutBudget(ctx context.Context, request PutBudgetRequestObject) (PutBudgetResponseObject, error)
	// ListAdminEvents What operators changed about the platform
	// (GET /admin/events)
	ListAdminEvents(ctx context.Context, request ListAdminEventsRequestObject) (ListAdminEventsResponseObject, error)
	// ListIntegrations Everything the platform is configured to talk to
	// (GET /admin/integrations)
	ListIntegrations(ctx context.Context, request ListIntegrationsRequestObject) (ListIntegrationsResponseObject, error)
	// DeleteMCPServer Remove a tool server
	// (DELETE /admin/integrations/mcp-servers/{name})
	DeleteMCPServer(ctx context.Context, request DeleteMCPServerRequestObject) (DeleteMCPServerResponseObject, error)
	// PutMCPServer Configure a tool server
	// (PUT /admin/integrations/mcp-servers/{name})
	PutMCPServer(ctx context.Context, request PutMCPServerRequestObject) (PutMCPServerResponseObject, error)
	// DeleteModelProvider Remove a model provider
	// (DELETE /admin/integrations/providers/{name})
	DeleteModelProvider(ctx context.Context, request DeleteModelProviderRequestObject) (DeleteModelProviderResponseObject, error)
	// PutModelProvider Configure a model provider
	// (PUT /admin/integrations/providers/{name})
	PutModelProvider(ctx context.Context, request PutModelProviderRequestObject) (PutModelProviderResponseObject, error)
	// ListTools Every tool the platform knows, and what it is classified as
	// (GET /admin/tools)
	ListTools(ctx context.Context, request ListToolsRequestObject) (ListToolsResponseObject, error)
	// ClassifyTool Record what a tool does to the world
	// (PUT /admin/tools/{toolId}/classification)
	ClassifyTool(ctx context.Context, request ClassifyToolRequestObject) (ClassifyToolResponseObject, error)
	// ListAgents Published agents
	// (GET /agents)
	ListAgents(ctx context.Context, request ListAgentsRequestObject) (ListAgentsResponseObject, error)
	// GetAgent One published agent, as it was published
	// (GET /agents/{agentId})
	GetAgent(ctx context.Context, request GetAgentRequestObject) (GetAgentResponseObject, error)
	// SetAgentPaused Start or stop an agent
	// (PUT /agents/{agentId}/paused)
	SetAgentPaused(ctx context.Context, request SetAgentPausedRequestObject) (SetAgentPausedResponseObject, error)
	// StartRun Open a run of this agent
	// (POST /agents/{agentId}/runs)
	StartRun(ctx context.Context, request StartRunRequestObject) (StartRunResponseObject, error)
	// PublishAgent Publish a new version of an agent
	// (PUT /agents/{agentId}/versions)
	PublishAgent(ctx context.Context, request PublishAgentRequestObject) (PublishAgentResponseObject, error)
	// ListWebhooks The webhook paths this agent declares
	// (GET /agents/{agentId}/webhooks)
	ListWebhooks(ctx context.Context, request ListWebhooksRequestObject) (ListWebhooksResponseObject, error)
	// RotateWebhookSecret Generate this webhook's secret
	// (POST /agents/{agentId}/webhooks/{path}/secret)
	RotateWebhookSecret(ctx context.Context, request RotateWebhookSecretRequestObject) (RotateWebhookSecretResponseObject, error)
	// ListApprovals The approval inbox
	// (GET /approvals)
	ListApprovals(ctx context.Context, request ListApprovalsRequestObject) (ListApprovalsResponseObject, error)
	// ListAudit What happened, across both records that keep it
	// (GET /audit)
	ListAudit(ctx context.Context, request ListAuditRequestObject) (ListAuditResponseObject, error)
	// GetCostRollup Consumption rolled up over a period
	// (GET /cost)
	GetCostRollup(ctx context.Context, request GetCostRollupRequestObject) (GetCostRollupResponseObject, error)
	// ListDecisions What the Gate has decided, most recent first
	// (GET /decisions)
	ListDecisions(ctx context.Context, request ListDecisionsRequestObject) (ListDecisionsResponseObject, error)
	// Health Liveness probe
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// ListPolicies The rules in force
	// (GET /policies)
	ListPolicies(ctx context.Context, request ListPoliciesRequestObject) (ListPoliciesResponseObject, error)
	// SimulatePolicy What a draft rule would have done
	// (POST /policies/simulate)
	SimulatePolicy(ctx context.Context, request SimulatePolicyRequestObject) (SimulatePolicyResponseObject, error)
	// DeletePolicy Remove a policy
	// (DELETE /policies/{code})
	DeletePolicy(ctx context.Context, request DeletePolicyRequestObject) (DeletePolicyResponseObject, error)
	// PutPolicy Write a policy
	// (PUT /policies/{code})
	PutPolicy(ctx context.Context, request PutPolicyRequestObject) (PutPolicyResponseObject, error)
	// ListRuns List runs
	// (GET /runs)
	ListRuns(ctx context.Context, request ListRunsRequestObject) (ListRunsResponseObject, error)
	// GetRunStats Aggregate counts over runs
	// (GET /runs/stats)
	GetRunStats(ctx context.Context, request GetRunStatsRequestObject) (GetRunStatsResponseObject, error)
	// GetThroughput Runs per hour, split by what became of them
	// (GET /runs/throughput)
	GetThroughput(ctx context.Context, request GetThroughputRequestObject) (GetThroughputResponseObject, error)
	// GetRun Get one run
	// (GET /runs/{runId})
	GetRun(ctx context.Context, request GetRunRequestObject) (GetRunResponseObject, error)
	// DecideApproval Approve or reject a suspended action
	// (POST /runs/{runId}/approvals)
	DecideApproval(ctx context.Context, request DecideApprovalRequestObject) (DecideApprovalResponseObject, error)
	// ListRunSteps Read the run's ledger trail
	// (GET /runs/{runId}/steps)
	ListRunSteps(ctx context.Context, request ListRunStepsRequestObject) (ListRunStepsResponseObject, error)
	// GetStepContent Read the content a step references
	// (GET /runs/{runId}/steps/{seq}/content)
	GetStepContent(ctx context.Context, request GetStepContentRequestObject) (GetStepContentResponseObject, error)
	// VerifyRun Verify the run's hash chain
	// (POST /runs/{runId}/verify)
	VerifyRun(ctx context.Context, request VerifyRunRequestObject) (VerifyRunResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListBudgets operation middleware
func (sh *strictHandler) ListBudgets(w http.ResponseWriter, r *http.Request) {
	var request ListBudgetsRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListBudgets(ctx, request.(ListBudgetsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListBudgets")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListBudgetsResponseObject); ok {
		if err := validResponse.VisitListBudgetsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

